# 14_projection_test.R: does the simulated ecology generate an explicit spread-by-position interaction beyond the nonlinear additive I-spline model? (explicit, model-free-of-replicate test)
# The KNOWN or independently estimated (Monte Carlo) response surface on the matched-profile grid is fitted, with the same fractional-logit machinery, I-spline bases, constraints and penalties, by
# (i) spread-only, (ii) additive nonlinear-position and (iii) interaction forms, using only cells supported by a reference sample (>= 30 sets in the (position, spread) window; 20,000 reference sets; 500 reference sites).
# If the interaction form reproduces the surface materially better than the additive form, the surface contains an explicit interaction beyond what the additive I-splines represent. Scenario "none" of Simulation A is the calibration (additive by construction), "strong" the positive control.
# Surface D2 = 1 - deviance(model) / deviance(constant) on the surface (response scale, equal weights); RMSE on link and response scales. Run from final/ (ZG_LIB6 set).
source("revision_sim/00_sim_common.R"); ORDERS <- c(2, 3, 4, 5, 8)
true_coef <- function(nm, sc) { b <- setNames(rep(0, length(nm)), nm); b["intercept"] <- -1; b[paste0("P_f", 1:3, "_L")] <- sc$L; b[paste0("P_f", 1:3, "_U")] <- sc$U; b[paste0("N_f", 1:3, "_L")] <- c(.9, .6, .4); b[paste0("N_f", 1:3, "_U")] <- c(.9, .6, .4); b["P"] <- .15; b["P_quadratic"] <- -.05; b["N"] <- -.10; b }
SCN <- list(none = list(L = c(1.2, .8, .5), U = c(1.2, .8, .5)), moderate = list(L = c(1.6, 1, .6), U = c(.8, .5, .3)), strong = list(L = c(2.4, 1.4, .8), U = c(.2, .1, .05)))
TB <- read.csv("revision_sim/tables/simB_truth_surfaces.csv"); rows <- list(); PEN0 <- PEN; PEN0[["interaction_shrink"]] <- 1e-6
for (src in c(paste0("A_", names(SCN)), "B_logistic", "B_control")) for (k in ORDERS) { isA <- startsWith(src, "A_"); set.seed(5150 + k); mu <- if (isA) 0 else .5; sdp <- if (isA) 1 else 1 / sqrt(12); P <- if (isA) rnorm(500) else runif(500); env <- data.frame(P = P, N = rnorm(500)); il <- sample_sets(500, k, 20000, seed = 9000 + k)
  grid <- data.frame(m = mu + sdp * GRID_STD$m, h = sdp * GRID_STD$h, m_std = GRID_STD$m, h_std = GRID_STD$h); sup <- support_cells(env$P, il, grid, k, WPOS * sdp, WSPR * sdp, 30); s <- sup$supported; if (sum(s) < 12) { rows[[length(rows) + 1]] <- data.frame(source = src, order = k, n_cells = sum(s), note = "too few supported cells"); next }
  dpop <- mk_design(env, il, "interaction"); sy <- surface_env(env, "P", grid[s, ], k)
  if (isA) { b <- true_coef(colnames(lay_fn(dpop$int, FALSE)$X), SCN[[sub("A_", "", src)]]); dsyn <- mk_design(sy$env, sy$idx, "interaction", ref = dpop); sy_all <- surface_env(env, "P", grid, k); da <- mk_design(sy_all$env, sy_all$idx, "interaction", ref = dpop); eta <- drop(lay_fn(da$int, FALSE)$X %*% b)[s]; resp <- plogis(eta) }
  else { rn <- "relative"; tt <- TB[TB$scenario == sub("B_", "", src) & TB$order == k, ]; resp <- tt[[rn]][s]; eta <- qlogis(pmin(pmax(resp, 1e-6), 1 - 1e-6)) }
  for (rn in if (isA) "known" else c("incidence", "relative", "occupancy", "heterogeneity")) { if (!isA) { tt <- TB[TB$scenario == sub("B_", "", src) & TB$order == k, ]; resp <- tt[[rn]][s]; eta <- qlogis(pmin(pmax(resp, 1e-6), 1 - 1e-6)) }
    for (kind in MODELS) { r <- tryCatch({ dtr <- mk_design(env, il, kind); ds <- mk_design(sy$env, sy$idx, kind, ref = dtr); f <- fit_model(kind, ds, resp, rep(1, length(resp)), PEN0); es <- eta_of(f, ds); p <- plogis(es); null <- bdev(resp, rep(mean(resp), length(resp)), rep(1, length(resp)))
      data.frame(source = src, response = rn, order = k, n_cells = sum(s), model = kind, surface_D2 = 1 - bdev(resp, p, rep(1, length(resp))) / null, rmse_link = sqrt(mean((es - eta)^2)), rmse_resp = sqrt(mean((p - resp)^2)), sd_resp = sd(resp), converged = isTRUE(f$converged), note = "") }, error = function(e) data.frame(source = src, response = rn, order = k, n_cells = sum(s), model = kind, surface_D2 = NA, rmse_link = NA, rmse_resp = NA, sd_resp = NA, converged = FALSE, note = conditionMessage(e))); rows[[length(rows) + 1]] <- r } } }
Pj <- bind_rows(rows); write.csv(Pj, "revision_sim/tables/projection_test.csv", row.names = FALSE); options(width = 200, digits = 3)
print(Pj |> filter(model != "spread_only") |> select(source, response, order, model, rmse_resp, sd_resp) |> tidyr::pivot_wider(names_from = model, values_from = rmse_resp) |> mutate(ratio_interaction_to_additive = interaction / additive) |> as.data.frame())
